"""Build the Mantle status ``Part`` for a terminal or interactive A2A state.

The dicts follow the inbound spike: public memory on ``completed``, the
active collect field on ``input_required``, and ``reason`` / ``error_*`` /
``canceled_skill`` for the other states. A public field marked ``pii`` is
anonymized with that field's method before it is copied. The short state
name stays inside the data dict. The proto state on the task is separate.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import Message, Part, TaskState

from rasa.core.a2a_server.proto_convert import data_part, text_part
from rasa.core.a2a_server.task_state_mapper import (
    TaskStateMappingResult,
    logical_task_state_name,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.a2a.task_state import (
    completed_user_facing_skill_ids,
    is_user_facing_skill,
    top_user_facing_frame,
)
from rasa.mantle.skills.skill import OrderedBlock
from rasa.mantle.skills.stack_frame_helpers import catalog_step_id
from rasa.mantle.skills.steps import CollectStep, Step
from rasa.privacy.mantle_anonymization import anonymize_memory_field_value

if TYPE_CHECKING:
    from rasa.mantle.skills.catalog import SkillCatalog
    from rasa.mantle.skills.skill import Skill
    from rasa.shared.core.trackers import DialogueStateTracker


class MantleStatusPayloadBuilder:
    """Assemble ``Part(data=...)`` and an optional text part for one state."""

    def __init__(
        self,
        catalog: "SkillCatalog",
        *,
        include_default_skills: bool = False,
    ) -> None:
        """Bind the catalog and whether advertised defaults publish memory."""
        self._catalog = catalog
        self._include_default_skills = include_default_skills

    def build(
        self,
        mapping: TaskStateMappingResult,
        tracker: "DialogueStateTracker | None",
        *,
        updater: TaskUpdater,
        user_visible_text: str | None = None,
    ) -> Message | None:
        """Return the status message, or ``None`` for a non-closing state.

        ``rejected`` keeps the decline out of the text part. The request type
        is ``reason`` on the data part. Other states may lead with the
        utterances already sent this turn.
        """
        if mapping.state not in {
            TaskState.TASK_STATE_COMPLETED,
            TaskState.TASK_STATE_INPUT_REQUIRED,
            TaskState.TASK_STATE_REJECTED,
            TaskState.TASK_STATE_FAILED,
            TaskState.TASK_STATE_CANCELED,
            TaskState.TASK_STATE_AUTH_REQUIRED,
        }:
            return None

        data = self._payload(mapping, tracker)
        parts: list[Part] = []
        if mapping.state != TaskState.TASK_STATE_REJECTED:
            text = (user_visible_text or "").strip()
            if text:
                parts.append(text_part(text))
        parts.append(data_part(data))
        return updater.new_agent_message(parts)

    def _payload(
        self,
        mapping: TaskStateMappingResult,
        tracker: "DialogueStateTracker | None",
    ) -> dict[str, Any]:
        data: dict[str, Any] = {"state": logical_task_state_name(mapping.state)}
        if tracker is None:
            return _failure_fields(mapping, data)

        if mapping.state == TaskState.TASK_STATE_COMPLETED:
            for skill_id in completed_user_facing_skill_ids(
                tracker,
                self._catalog,
                include_default_skills=self._include_default_skills,
            ):
                skill = self._catalog.skill_by_id(skill_id)
                if skill is None:
                    continue
                data[skill_id] = _set_public_memory(skill, tracker)
            return data

        if mapping.state == TaskState.TASK_STATE_INPUT_REQUIRED:
            data.update(self._input_required_fields(tracker))
            return data

        if mapping.state == TaskState.TASK_STATE_REJECTED:
            if mapping.reason is not None:
                data["reason"] = mapping.reason
            return data

        if mapping.state == TaskState.TASK_STATE_CANCELED:
            if mapping.canceled_skill is not None:
                data["canceled_skill"] = mapping.canceled_skill
            return data

        return _failure_fields(mapping, data)

    def _input_required_fields(self, tracker: "DialogueStateTracker") -> dict[str, Any]:
        frame = top_user_facing_frame(
            tracker,
            self._catalog,
            include_default_skills=self._include_default_skills,
        )
        if frame is None:
            return {}
        skill = self._catalog.skill_by_id(frame.skill_id)
        fields: dict[str, Any] = {"active_skill": frame.skill_id}
        # A prose frame has no authored step. ``catalog_step_id`` would publish
        # the engine sentinel ``autonomous``.
        if isinstance(frame, OrderedBlockStackFrame):
            fields["active_step"] = catalog_step_id(frame)
        if skill is None or not is_user_facing_skill(
            skill, include_default_skills=self._include_default_skills
        ):
            return fields
        step = _step_for_frame(skill, frame)
        if isinstance(step, CollectStep) and _is_public_field(skill, step.collect):
            fields[step.collect] = _published_public_value(
                skill, step.collect, tracker.get_slot(f"{skill.id}.{step.collect}")
            )
            return fields
        fields.update(_set_public_memory(skill, tracker))
        return fields


def _failure_fields(
    mapping: TaskStateMappingResult, data: dict[str, Any]
) -> dict[str, Any]:
    if mapping.state != TaskState.TASK_STATE_FAILED:
        return data
    if mapping.error_type is not None:
        data["error_type"] = mapping.error_type
    if mapping.error_info is not None:
        data["error_info"] = mapping.error_info
    return data


def _is_public_field(skill: "Skill", name: str) -> bool:
    """Whether *name* is public and does not also exist as private.

    Private wins the tracker slot on a name collision, so a collect step for
    that name must not copy the slot into ``input_required``.
    """
    definition = skill.memory.definition
    if name in definition.private:
        return False
    return name in definition.public


def _set_public_memory(
    skill: "Skill", tracker: "DialogueStateTracker"
) -> dict[str, Any]:
    """Public fields that have a value. Private and ``system.*`` stay out.

    A private field with the same name occupies the one tracker slot for that
    name, so the public entry is skipped rather than publishing the private
    value. A public ``pii`` field is anonymized before it is copied.
    """
    private_names = skill.memory.definition.private
    values: dict[str, Any] = {}
    for name in skill.memory.definition.public:
        if name in private_names:
            continue
        value = tracker.get_slot(f"{skill.id}.{name}")
        # ``None`` means unset. A value equal to ``initial_value``, including
        # ``0`` or ``False``, was written and still belongs on the payload.
        if value is None:
            continue
        values[name] = _published_public_value(skill, name, value)
    return values


def _published_public_value(skill: "Skill", name: str, value: Any) -> Any:
    """Copy *value*, anonymized when the public field is marked ``pii``."""
    field = skill.memory.definition.public.get(name)
    if field is None:
        return value
    return anonymize_memory_field_value(field, f"{skill.id}.{name}", value)


def _step_for_frame(
    skill: "Skill", frame: SkillStackFrame | OrderedBlockStackFrame
) -> Step | None:
    """The ordered-block step under *frame*, or ``None`` for a prose frame."""
    if not isinstance(frame, OrderedBlockStackFrame):
        return None
    for block in skill.body:
        if isinstance(block, OrderedBlock) and block.block_id == frame.block_id:
            return block.step_by_id(frame.step_id)
    return None
